// Sets the small icon + accent colour Android uses for push notifications
// (status bar and notification header). android/ is generated by prebuild, so
// this has to live in a config plugin rather than in AndroidManifest.xml.
const {
  AndroidConfig,
  withAndroidColors,
  withAndroidManifest,
  withDangerousMod,
} = require("expo/config-plugins");
const fs = require("fs");
const path = require("path");

const ICON_NAME = "ic_notification";
const COLOR_NAME = "notification_icon_color";
const DENSITIES = ["mdpi", "hdpi", "xhdpi", "xxhdpi", "xxxhdpi"];

const withIconFiles = (config, { iconDir }) =>
  withDangerousMod(config, [
    "android",
    async (cfg) => {
      const resDir = path.join(
        cfg.modRequest.platformProjectRoot,
        "app/src/main/res",
      );
      for (const density of DENSITIES) {
        const from = path.join(
          cfg.modRequest.projectRoot,
          iconDir,
          `${ICON_NAME}-${density}.png`,
        );
        const toDir = path.join(resDir, `drawable-${density}`);
        fs.mkdirSync(toDir, { recursive: true });
        fs.copyFileSync(from, path.join(toDir, `${ICON_NAME}.png`));
      }
      return cfg;
    },
  ]);

const withIconColor = (config, { color }) =>
  withAndroidColors(config, (cfg) => {
    cfg.modResults = AndroidConfig.Colors.assignColorValue(cfg.modResults, {
      name: COLOR_NAME,
      value: color,
    });
    return cfg;
  });

// Firebase reads this when it draws a notification message itself (app in
// background/closed). The colour meta-data comes from firebase.json, because
// @react-native-firebase/messaging already declares it.
const withIconMetaData = (config) =>
  withAndroidManifest(config, (cfg) => {
    const app = AndroidConfig.Manifest.getMainApplicationOrThrow(cfg.modResults);
    AndroidConfig.Manifest.addMetaDataItemToMainApplication(
      app,
      "com.google.firebase.messaging.default_notification_icon",
      `@drawable/${ICON_NAME}`,
      "resource",
    );
    return cfg;
  });

module.exports = function withNotificationIcon(
  config,
  { iconDir = "assets/images/notification-icon", color = "#2d6b06" } = {},
) {
  config = withIconFiles(config, { iconDir });
  config = withIconColor(config, { color });
  config = withIconMetaData(config);
  return config;
};
